create table if not exists public.planner_presets ( id uuid primary key default gen_random_uuid(), owner_id uuid not null default auth.uid() references public.profiles(id) on delete cascade, name text not null check (char_length(btrim(name)) between 1 and 60), color text check (color is null or color in ('red','orange','gold','green','teal','blue','purple','pink')), default_minutes integer not null default 60 check (default_minutes between 5 and 1440), calendar_kind text not null default 'other' check (calendar_kind in ('shoot','call','meeting','deadline','other')), position integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now() ); create unique index if not exists planner_presets_owner_name on public.planner_presets (owner_id, lower(btrim(name))); create index if not exists planner_presets_owner_position on public.planner_presets (owner_id, position); create table if not exists public.planner_blocks ( id uuid primary key default gen_random_uuid(), owner_id uuid not null default auth.uid() references public.profiles(id) on delete cascade, title text not null check (char_length(btrim(title)) between 1 and 120), notes text not null default '' check (char_length(notes) <= 2000), weekday smallint not null check (weekday between 0 and 6), start_minute integer not null check (start_minute between 0 and 1439), end_minute integer not null check (end_minute between 1 and 1440), on_date date, repeats boolean not null default false, color text check (color is null or color in ('red','orange','gold','green','teal','blue','purple','pink')), calendar_kind text not null default 'other' check (calendar_kind in ('shoot','call','meeting','deadline','other')), schedule_event_id uuid references public.schedule_events(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint planner_blocks_ends_after_start check (end_minute > start_minute), constraint planner_blocks_date_matches_repeat check ((repeats and on_date is null) or (not repeats and on_date is not null)) ); create index if not exists planner_blocks_owner_date on public.planner_blocks (owner_id, on_date); create index if not exists planner_blocks_owner_repeating on public.planner_blocks (owner_id, weekday) where repeats; create or replace function public.set_planner_block_weekday() returns trigger language plpgsql as $$ begin if new.on_date is not null then new.weekday := extract(isodow from new.on_date)::int - 1; end if; return new; end; $$; drop trigger if exists planner_blocks_weekday on public.planner_blocks; create trigger planner_blocks_weekday before insert or update of on_date on public.planner_blocks for each row execute procedure public.set_planner_block_weekday(); create or replace function public.touch_updated_at() returns trigger language plpgsql as $$ begin new.updated_at := now(); return new; end; $$; drop trigger if exists planner_presets_touch on public.planner_presets; create trigger planner_presets_touch before update on public.planner_presets for each row execute procedure public.touch_updated_at(); drop trigger if exists planner_blocks_touch on public.planner_blocks; create trigger planner_blocks_touch before update on public.planner_blocks for each row execute procedure public.touch_updated_at(); alter table public.planner_presets enable row level security; alter table public.planner_blocks enable row level security; drop policy if exists "planner_presets: owner only" on public.planner_presets; create policy "planner_presets: owner only" on public.planner_presets for all using (owner_id = auth.uid()) with check (owner_id = auth.uid()); drop policy if exists "planner_blocks: owner only" on public.planner_blocks; create policy "planner_blocks: owner only" on public.planner_blocks for all using (owner_id = auth.uid()) with check (owner_id = auth.uid()); revoke all on public.planner_presets from anon; revoke all on public.planner_blocks from anon;
